import type { FC, ReactNode } from 'react';
import { useEffect } from 'react';
import { Link } from 'react-router-dom';
import portfolioData from '@/data/portfolio.json';

interface ShareLayoutProps {
  title: string;
  toolPath: string;
  toolName: string;
  children: ReactNode;
}

// Deliberately bare: no Navbar, no ToolsSidebar, no rest-of-site chrome —
// this is what a shared result link renders, so the visitor sees only the
// result plus a way back to the live tool. Rendered as a sibling of
// SiteLayout in App.tsx, not nested under it. Branding is intentionally
// minimal: the tool name up top (linking to the live tool) and a small
// "Made by shravan" credit at the bottom (linking home) — no navbar, no
// prominent CTA button.
const ShareLayout: FC<ShareLayoutProps> = ({ title, toolPath, toolName, children }) => {
  useEffect(() => {
    const previousTitle = document.title;
    document.title = `${title} | ${portfolioData.abbrName}`;

    const meta = document.createElement('meta');
    meta.name = 'robots';
    meta.content = 'noindex';
    document.head.appendChild(meta);

    return () => {
      document.title = previousTitle;
      document.head.removeChild(meta);
    };
  }, [title]);

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col">
      <header className="section-container py-5">
        <Link
          to={toolPath}
          className="inline-block px-3 py-1.5 -mx-3 text-xl font-display font-bold text-accent tracking-tight rounded-full hover:bg-accent/10 transition-colors"
        >
          {toolName}
        </Link>
      </header>

      <main className="section-container flex-1 pb-16">{children}</main>

      <footer className="section-container py-8 text-center text-sm text-muted-foreground">
        Made by{' '}
        <Link to="/" className="font-medium text-accent hover:underline">
          {portfolioData.abbrName}
        </Link>
      </footer>
    </div>
  );
};

export default ShareLayout;
